package edu.ankara.audiometer.property;
import edu.ankara.audiometer.application.SerialMessageProcessor;import edu.ankara.audiometer.domain.algorithm.*;import edu.ankara.audiometer.domain.config.*;import edu.ankara.audiometer.domain.model.*;import edu.ankara.audiometer.infrastructure.export.CsvAudiogramExporter;import edu.ankara.audiometer.infrastructure.serial.SerialProtocol;import net.jqwik.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class AudiometryStatePropertiesTest { AudiometryConfig c=AudiometryConfig.defaults(); @Property void invalidRawMessagesNeverCrashParser(@ForAll String raw){ assertDoesNotThrow(()->SerialProtocol.parseResponseMessage(raw)); } @Property void repeatedTransitionsProduceValidState(@ForAll @Size(max=30) List<Boolean> heard){ var s=TestState.initial(c); for(boolean h:heard){ s=HughsonWestlakeEngine.presentTone(s); s=HughsonWestlakeEngine.applyResponseToLastPresentation(s,h?PatientResponse.HEARD:PatientResponse.NOT_HEARD); assertNotNull(s.currentEar()); assertTrue(c.frequencyPlan().activeOrder().contains(s.currentFrequency())); } } @Property void csvRowsMatchAudiogramPointCount(@ForAll @IntRange(min=0,max=5) int count){ var a=Audiogram.empty(); for(int i=0;i<count;i++) a=a.add(new AudiogramPoint(i%2==0?Ear.RIGHT:Ear.LEFT,new FrequencyHz(List.of(250,500,1000,2000,4000).get(i)),new IntensityDbHL(20+i),ThresholdCriterion.TWO_OUT_OF_THREE_ASCENDING,3,i,"n"),true); var s=TestState.initial(c).withAudiogram(a); assertEquals(count+1,new CsvAudiogramExporter().export(s).lines().count()); } @Property void noDuplicateThresholdWithoutRetest(@ForAll @IntRange(min=0,max=80) int db){ var a=Audiogram.empty(); var p=new AudiogramPoint(Ear.RIGHT,new FrequencyHz(1000),new IntensityDbHL(db),ThresholdCriterion.TWO_OUT_OF_THREE_ASCENDING,3,1,"a"); a=a.add(p,false).add(p,false); assertEquals(1,a.points().size()); } @Example void pureMessageReducerIsDeterministic(){ var raw=List.of(" RESPONSE ","bad","response"); var p=new SerialMessageProcessor(SerialProtocolConfig.defaults()); var s=TestState.initial(c); assertEquals(p.process(s,raw),p.process(s,raw)); } }
